from PIL import Image,ImageFilter
from pathlib import Path
import zipfile
p=Path('/mnt/data/prizvannyy_battle_v003');p.mkdir(exist_ok=True)
for name,fn in [('hero','1000076438.png'),('wolf','1000076437.png')]:
 im=Image.open('/mnt/data/'+fn).convert('RGBA'); w,h=im.size
 for i,(x,y) in enumerate([(0,0),(1,0),(0,1),(1,1)]):
  q=im.crop((x*w//2,y*h//2,(x+1)*w//2,(y+1)*h//2))
  px=q.load()
  for yy in range(q.height):
   for xx in range(q.width):
    r,g,b,a=px[xx,yy]; v=max(r,g,b);spread=max(r,g,b)-min(r,g,b)
    # original near-charcoal matte; preserve colorful parts
    alpha=255 if v>77 or spread>28 else max(0,min(255,int((v-34)*6)))
    px[xx,yy]=(r,g,b,alpha)
  q.save(p/f'{name}{i}.png')
Image.open('/mnt/data/1000076435.png').save(p/'arena.png')
html='''<!doctype html><html lang="ru"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1,maximum-scale=1,user-scalable=no"><title>Призванный — бой v0.0.3</title><style>
*{box-sizing:border-box}body{margin:0;background:#090711;color:#fff;font-family:system-ui,Arial;display:grid;place-items:center;min-height:100dvh}.game{width:min(100vw,calc(100dvh * 9 / 16),480px);aspect-ratio:9/16;position:relative;overflow:hidden;background:#20122b url(arena.png) center/100% 100% no-repeat;isolation:isolate}.game:before{content:"";position:absolute;inset:0;background:linear-gradient(#080516a8 0%,transparent 22%,transparent 58%,#080518df 100%);pointer-events:none;z-index:1}.top{position:absolute;z-index:5;top:2%;left:4%;right:4%;display:flex;justify-content:space-between;align-items:center;text-shadow:0 2px 5px #000}.pill{border:1px solid #9e75cfaa;background:#120b26cc;border-radius:20px;padding:7px 12px;font-size:12px}.floor{font-size:15px;font-weight:800;color:#f2d69a}.arena-name{position:absolute;top:9%;width:100%;text-align:center;font-size:12px;letter-spacing:2px;color:#e8caff;text-shadow:0 2px 8px #000;z-index:4}.stage{position:absolute;inset:19% 0 20%;z-index:2}.fighter{position:absolute;width:53%;height:55%;bottom:7%;transform-origin:50% 85%;filter:drop-shadow(0 6px 9px #0b061a);transition:filter .2s}.fighter img{position:absolute;width:100%;height:100%;object-fit:contain;object-position:center bottom;display:block}.hero{left:-3%;animation:idleHero 2.8s ease-in-out infinite}.wolf{right:-3%;bottom:10%;width:53%;height:49%;animation:idleWolf 1.9s ease-in-out infinite}.hero img{transform:scaleX(-1)}.wolf img{transform:scaleX(-1)}@keyframes idleHero{0%,100%{transform:translateY(0) rotate(-.6deg)}50%{transform:translateY(-4px) rotate(.6deg)}}@keyframes idleWolf{0%,100%{transform:translateY(0) scale(1)}50%{transform:translateY(-3px) scale(1.018)}}.hero.attack{animation:slash .45s ease-out}.wolf.attack{animation:lunge .48s ease-out}.hit{filter:brightness(2.5) drop-shadow(0 0 20px #df7bff)!important}@keyframes slash{0%{transform:translateX(0)}45%{transform:translateX(19%) rotate(4deg)}100%{transform:translateX(0)}}@keyframes lunge{0%{transform:translateX(0)}45%{transform:translateX(-21%)}100%{transform:translateX(0)}}.dead{animation:die 1.5s ease-in forwards!important}@keyframes die{0%{opacity:1;transform:translateY(0) scale(1)}40%{opacity:1;transform:translateY(16%) scale(.97)}100%{opacity:0;transform:translateY(26%) scale(.83);filter:blur(15px) brightness(2)}}.barwrap{position:absolute;z-index:4;width:41%;top:31%;text-align:center;font-size:11px;text-shadow:0 2px 4px #000}.barwrap.left{left:4%}.barwrap.right{right:4%}.bar{height:7px;background:#1c1029;border:1px solid #a780b8;border-radius:10px;overflow:hidden;margin-top:5px}.fill{height:100%;background:linear-gradient(90deg,#5ccead,#a6ffd5);transition:width .3s}.enemyfill{background:linear-gradient(90deg,#b33175,#ff719f)}.slashfx{position:absolute;z-index:4;top:45%;left:50%;width:26%;height:7%;border-top:5px solid #f3d0ff;border-radius:50%;filter:drop-shadow(0 0 12px #bf31ff);transform:rotate(-35deg);opacity:0;pointer-events:none}.slashfx.show{animation:fx .32s ease-out}@keyframes fx{0%{opacity:0;transform:scale(.4) rotate(-35deg)}35%{opacity:1}100%{opacity:0;transform:scale(1.5) rotate(-35deg)}}.dmg{position:absolute;top:43%;right:15%;z-index:6;font-weight:900;font-size:21px;color:#ffe1fb;text-shadow:0 0 12px #a317f5;opacity:0}.dmg.show{animation:dmg .7s ease-out}@keyframes dmg{0%{opacity:1;transform:translateY(0)}100%{opacity:0;transform:translateY(-50px)}}.bottom{position:absolute;z-index:5;bottom:2%;left:4%;right:4%;border:1px solid #70549b;background:#110b25d9;border-radius:15px;padding:12px}.status{display:flex;justify-content:space-between;gap:10px;font-size:12px;margin-bottom:10px}.controls{display:flex;gap:8px}.controls button{flex:1;border:1px solid #b886f5;background:linear-gradient(#47266c,#261443);color:white;border-radius:9px;padding:11px 5px;font-weight:700;font-size:12px}.controls button:active{transform:scale(.97)}.note{font-size:10px;color:#c2a7d7;margin-top:9px;text-align:center}.tag{position:absolute;z-index:5;bottom:19%;width:100%;text-align:center;font-size:12px;color:#f3d0ff;text-shadow:0 0 8px #000}
</style><div class="game"><div class="top"><div class="floor">⚔ Этаж <span id="floor">1</span></div><div class="pill">✦ DPS <span id="dps">125</span></div></div><div class="arena-name">ЗАЛ ТЕНЕЙ</div><div class="barwrap left">Теневой мечник<div class="bar"><div id="hh" class="fill" style="width:100%"></div></div></div><div class="barwrap right">Теневой волк<div class="bar"><div id="wh" class="fill enemyfill" style="width:100%"></div></div></div><div class="stage"><div id="hero" class="fighter hero"><img id="heroimg" src="hero0.png"></div><div id="wolf" class="fighter wolf"><img id="wolfimg" src="wolf0.png"></div><div id="fx" class="slashfx"></div><div id="dmg" class="dmg">−125</div></div><div class="tag" id="tag">Автоматический бой</div><div class="bottom"><div class="status"><span>⚔ Мечник · ранг B</span><span id="result">Враг: 100%</span></div><div class="controls"><button id="toggle">⏸ Пауза</button><button id="speed">×1 Скорость</button><button id="restart">↻ Повторить</button></div><div class="note">v0.0.3 · тест анимации · изображения из референсов</div></div></div><script>
let hp=100,heroHp=100,floor=1,running=true,speed=1,dead=false,lock=false;const $=id=>document.getElementById(id);let tick=0;
function setPose(who,n){$(who+'img').src=who+n+'.png'}
function flash(id,cls,dur){let e=$(id);e.classList.remove(cls);void e.offsetWidth;e.classList.add(cls);setTimeout(()=>e.classList.remove(cls),dur)}
function attack(){if(!running||dead||lock)return;lock=true;setPose('hero',1);flash('hero','attack',460);setTimeout(()=>{if(!running)return;flash('fx','show',320);flash('wolf','hit',230);hp=Math.max(0,hp-25);$('wh').style.width=hp+'%';$('result').textContent='Враг: '+hp+'%';$('dmg').textContent='−125';flash('dmg','show',700);setPose('wolf',hp===0?3:2);if(hp===0){dead=true;$('wolf').classList.add('dead');$('tag').textContent='ПОБЕДА';setTimeout(()=>{if(running)next()},1800)}else{setTimeout(()=>setPose('wolf',0),360)}},240/speed);setTimeout(()=>{setPose('hero',0);lock=false},700/speed)}
function next(){floor++;$('floor').textContent=floor;hp=100;dead=false;heroHp=Math.min(100,heroHp+10);$('hh').style.width=heroHp+'%';$('wh').style.width='100%';$('result').textContent='Враг: 100%';$('tag').textContent='Автоматический бой';$('wolf').classList.remove('dead');setPose('wolf',0)}
function enemyAttack(){if(!running||dead||lock)return;setPose('wolf',1);flash('wolf','attack',480);setTimeout(()=>{heroHp=Math.max(10,heroHp-8);$('hh').style.width=heroHp+'%';flash('hero','hit',200);setPose('hero',2)},200/speed);setTimeout(()=>{setPose('wolf',0);setPose('hero',0)},650/speed)}
let timer=setInterval(()=>{if(!running)return;tick++;if(tick%4===3)enemyAttack();else attack()},1050);
$('toggle').onclick=()=>{running=!running;$('toggle').textContent=running?'⏸ Пауза':'▶ Продолжить'};
$('speed').onclick=()=>{speed=speed===1?2:1;$('speed').textContent='×'+speed+' Скорость';clearInterval(timer);timer=setInterval(()=>{if(!running)return;tick++;if(tick%4===3)enemyAttack();else attack()},1050/speed)};
$('restart').onclick=()=>{floor=0;heroHp=100;$('hh').style.width='100%';running=true;$('toggle').textContent='⏸ Пауза';next()};
</script></html>'''
